/**
 * Small summary of today's Riskometer reading (EUR/CHF), used by the top nav dot and the
 * home page mini gauge. Generated by scripts/build-riskometer.ts into src/data/fx/summary.json.
 * Returns null if the data has not been built yet.
 */
import type { LevelIndex } from '@/i18n/dict/levels';

export interface RiskSummary {
  pair: string;
  asOf: string;
  /** Realised 1-month volatility in percent, e.g. 6.04. */
  vol: number;
  level: LevelIndex;
  /** Percentile rank 0..100 among daily values since 2006. */
  percentile: number;
  /** Needle position 0..5 (segment index + share within the level). */
  needle: number;
}

const files = import.meta.glob<{ default: RiskSummary }>('../data/fx/summary.json', {
  eager: true,
});

export function getRiskSummary(): RiskSummary | null {
  const mod = Object.values(files)[0];
  return mod ? mod.default : null;
}
